VAR
    Overload_Timer : TON;
END_VAR

Overload_Timer(IN := Motor_Running AND (Motor_Current > 41.5), PT := T#10S);

Overload_Alarm := (Motor_Current > 41.5) OR (Motor_Winding_Temp > 110.0);

IF Motor_Winding_Temp > 120.0 THEN
    Safe_Mode_Active := TRUE;
ELSIF Fault_Reset AND (Motor_Winding_Temp <= 100.0) THEN
    Safe_Mode_Active := FALSE;
END_IF;

IF (Motor_Winding_Temp >= 130.0) OR Overload_Timer.Q THEN
    Motor_Stop := TRUE;
ELSIF Fault_Reset THEN
    Motor_Stop := FALSE;
END_IF;

